/**
 * Browser compositor for the vector Glitch avatar: paints js/avatar-rig.js
 * draw lists with Canvas2D (Path2D fills, gradient and bitmap fills, masks)
 * and bakes a look into the same one-sheet-per-animation layout the game
 * reads from js/avatar-anims.js (GLITCH_AVATAR), at 1x or 3x.
 *
 * The same code renders the shipped default sheets offline (tools/
 * avatar-compositor/build.mjs drives it in Chromium), so a look baked at
 * runtime and the files on disk are pixel-for-pixel the same pipeline.
 *
 * Data (assets/avatar/, generated by tools/avatar-compositor/build.mjs):
 *  - base.json: the rig (Avatar.swf avatarContainer, frame table) and body shapes
 *  - articles/<type>/<name>.json: one article's parts per frame and shapes
 *  - catalog.json: what the character builder offers, colours from GSJS
 */
import { SHEET_FRAMES } from './avatar-anims.js';
import { applyCM, drawListBounds, expandRig, frameDrawList, lookMatrices, slotAssignments } from './avatar-rig.js';

export const AVATAR_DATA_DIR = 'assets/avatar/';
/** Widest sheet row at 3x (px); taller sheets wrap into rows. */
export const SHEET_MAX_WIDTH_3X = 4096;
/** Sheets in bake order (the stand/walk sheet first, emotions last). */
export const SHEET_ORDER = Object.freeze(['base', 'jump', 'climb', 'happy', 'surprise', 'angry']);

const rgba = (c, a = 1) => `rgba(${Math.round(c[0])},${Math.round(c[1])},${Math.round(c[2])},${Math.max(0, Math.min(1, c[3] * a)).toFixed(4)})`;

/** Path2D per (source, shape, path index). */
const pathCache = new Map();
function pathOf(src, id, i, d) {
  const key = `${src}:${id}:${i}`;
  let p = pathCache.get(key);
  if (!p) { p = new Path2D(d); pathCache.set(key, p); }
  return p;
}

/** Bitmap fills recoloured by a colour matrix (the skin texture). */
const tintCache = new Map();
function tintedBitmap(img, cm, key) {
  if (!cm) return img;
  const k = `${key}|${cm.map((v) => v.toFixed(4)).join(',')}`;
  let c = tintCache.get(k);
  if (c) return c;
  c = document.createElement('canvas');
  c.width = img.width;
  c.height = img.height;
  const g = c.getContext('2d');
  g.drawImage(img, 0, 0);
  const data = g.getImageData(0, 0, c.width, c.height);
  const px = data.data;
  for (let i = 0; i < px.length; i += 4) {
    const o = applyCM(cm, [px[i], px[i + 1], px[i + 2], px[i + 3] / 255]);
    px[i] = o[0]; px[i + 1] = o[1]; px[i + 2] = o[2]; px[i + 3] = o[3] * 255;
  }
  g.putImageData(data, 0, 0);
  tintCache.set(k, c);
  return c;
}

/**
 * Paint draw items. sources: Map<src, { shapes, bitmaps: Map<id, image> }>.
 * base: device transform [a,b,c,d,e,f] applied before each item's matrix.
 */
export function paintItems(ctx, items, sources, base) {
  for (const it of items) {
    if (it.clip) { paintClipped(ctx, it, sources, base); continue; }
    const src = sources.get(it.src);
    const shape = src?.shapes?.[it.s];
    if (!shape || (it.a ?? 1) <= 0) continue;
    const m = mul(base, it.m);
    const devScale = Math.sqrt(Math.abs(m[0] * m[3] - m[1] * m[2])) || 1;
    for (let i = 0; i < shape.p.length; i++) {
      const p = shape.p[i];
      const path = pathOf(it.src, it.s, i, p.d);
      ctx.setTransform(m[0], m[1], m[2], m[3], m[4], m[5]);
      const f = p.f;
      if (f) {
        if (Array.isArray(f)) {
          ctx.fillStyle = rgba(applyCM(it.cm, f), it.a ?? 1);
          ctx.fill(path, p.r || 'nonzero');
        } else if (f.t === 'l' || f.t === 'r') {
          ctx.save();
          ctx.clip(path, p.r || 'nonzero');
          ctx.transform(f.m[0], f.m[1], f.m[2], f.m[3], f.m[4], f.m[5]);
          const g = f.t === 'l' ? ctx.createLinearGradient(-819.2, 0, 819.2, 0) : ctx.createRadialGradient(f.fx || 0, 0, 0, 0, 0, 819.2);
          for (const s of f.st) g.addColorStop(Math.max(0, Math.min(1, s[0])), rgba(applyCM(it.cm, [s[1], s[2], s[3], s[4]]), it.a ?? 1));
          ctx.fillStyle = g;
          ctx.fillRect(-32768, -32768, 65536, 65536);
          ctx.restore();
        } else if (f.t === 'b') {
          const img = src.bitmaps?.get(f.id);
          if (img) {
            const pat = ctx.createPattern(tintedBitmap(img, it.cm, `${it.src}:${f.id}`), 'repeat');
            pat.setTransform(new DOMMatrix([f.m[0], f.m[1], f.m[2], f.m[3], f.m[4], f.m[5]]));
            ctx.globalAlpha = it.a ?? 1;
            ctx.fillStyle = pat;
            ctx.fill(path, p.r || 'nonzero');
            ctx.globalAlpha = 1;
          }
        }
      }
      if (p.s) {
        // Flash draws lines at least one device pixel wide.
        ctx.lineWidth = Math.max(p.s.w, 1 / devScale);
        ctx.lineCap = p.s.cap === 'none' ? 'butt' : p.s.cap;
        ctx.lineJoin = p.s.join;
        ctx.strokeStyle = rgba(applyCM(it.cm, p.s.c), it.a ?? 1);
        ctx.stroke(path);
      }
    }
  }
  ctx.setTransform(1, 0, 0, 1, 0, 0);
}

function paintClipped(ctx, group, sources, base) {
  const clip = new Path2D();
  for (const c of group.clip) {
    const m = mul(base, c.m);
    const dm = new DOMMatrix([m[0], m[1], m[2], m[3], m[4], m[5]]);
    if (c.rect) {
      const r = new Path2D();
      r.rect(c.rect[0], c.rect[1], c.rect[2], c.rect[3]);
      clip.addPath(r, dm);
      continue;
    }
    const shape = sources.get(c.src)?.shapes?.[c.s];
    if (!shape) continue;
    shape.p.forEach((p, i) => { if (p.f) clip.addPath(pathOf(c.src, c.s, i, p.d), dm); });
  }
  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.clip(clip);
  paintItems(ctx, group.items, sources, base);
  ctx.restore();
}

function mul(p, c) {
  return [
    p[0] * c[0] + p[2] * c[1], p[1] * c[0] + p[3] * c[1],
    p[0] * c[2] + p[2] * c[3], p[1] * c[2] + p[3] * c[3],
    p[0] * c[4] + p[2] * c[5] + p[4], p[1] * c[4] + p[3] * c[5] + p[5],
  ];
}

// ---------------------------------------------------------------------------
// Loading
// ---------------------------------------------------------------------------

const jsonCache = new Map();
function loadJson(url) {
  if (!jsonCache.has(url)) {
    jsonCache.set(url, fetch(url).then((r) => {
      if (!r.ok) throw new Error(`${url}: ${r.status}`);
      return r.json();
    }).catch((err) => { jsonCache.delete(url); throw err; }));
  }
  return jsonCache.get(url);
}

function loadImage(url) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error(`image ${url}`));
    img.src = url;
  });
}

async function sourceFrom(data, dir) {
  const bitmaps = new Map();
  for (const [id, file] of Object.entries(data.bitmaps || {})) bitmaps.set(Number(id), await loadImage(`${dir}${file}`));
  return { shapes: data.shapes, bitmaps };
}

/** The rig and the base shapes (cached). */
export async function loadRig(dir = AVATAR_DATA_DIR) {
  const base = expandRig(await loadJson(`${dir}base.json`));
  if (!base._source) base._source = await sourceFrom(base, dir);
  return base;
}

export async function loadCatalog(dir = AVATAR_DATA_DIR) {
  return loadJson(`${dir}catalog.json`);
}

/** Article data for every part of an outfit. */
export async function loadArticles(outfit, dir = AVATAR_DATA_DIR) {
  const out = new Map();
  const sources = new Map();
  await Promise.all(Object.entries(outfit || {}).map(async ([type, a]) => {
    if (!a || !a.name || a.name === 'none') return;
    const data = await loadJson(`${dir}articles/${type}/${a.name}.json`);
    out.set(a.name, data);
    sources.set(a.name, await sourceFrom(data, dir));
  }));
  return { articles: out, sources };
}

// ---------------------------------------------------------------------------
// Baking
// ---------------------------------------------------------------------------

/**
 * Everything frameDrawList needs for a look:
 * look = { outfit: { type: { name, colors } }, colors: { skin: {color_1}, hair: {color_1, color_10} }, face }
 */
export async function prepareLook(look, dir = AVATAR_DATA_DIR) {
  const [rig, catalog] = await Promise.all([loadRig(dir), loadCatalog(dir)]);
  const { articles, sources } = await loadArticles(look.outfit, dir);
  sources.set('base', rig._source);
  const allowsHair = (hat, hair) => Boolean(catalog.hatHair?.[hat.name]?.includes(hair.name));
  const ctx = {
    rig,
    sources,
    look: { assign: slotAssignments(look.outfit, { hatAllowsHair: allowsHair }), articles, matrices: lookMatrices(look), face: look.face || {} },
  };
  ctx.shapeOf = (src, id) => sources.get(src)?.shapes?.[id];
  return ctx;
}

/** Draw list for a swf frame number. */
export function drawListFor(prep, swfFrame) {
  const i = prep.rig.frames.indexOf(swfFrame);
  return i < 0 ? [] : frameDrawList(prep.rig, prep.look, i);
}

/**
 * Cell layout for one sheet (1x units): union of the frames' bounds, the
 * avatar origin (its feet, between them) at (ox, oy), rows that fit
 * SHEET_MAX_WIDTH_3X.
 */
export function sheetLayout(prep, name) {
  const frames = SHEET_FRAMES[name];
  let b = null;
  for (const fn of frames) {
    const r = drawListBounds(drawListFor(prep, fn), prep.shapeOf);
    if (r) b = b ? [Math.min(b[0], r[0]), Math.min(b[1], r[1]), Math.max(b[2], r[2]), Math.max(b[3], r[3])] : r;
  }
  b = b || [-1, -1, 1, 1];
  const ox = Math.floor(-b[0]) + 1;
  const oy = Math.floor(-b[1]) + 1;
  const fw = ox + Math.ceil(b[2]) + 1;
  const fh = oy + Math.ceil(b[3]) + 1;
  // As few rows as the width allows, then as few columns as those rows need.
  const maxCols = Math.max(1, Math.min(frames.length, Math.floor(SHEET_MAX_WIDTH_3X / (fw * 3))));
  const rows = Math.ceil(frames.length / maxCols);
  const cols = Math.ceil(frames.length / rows);
  // Anchor every sheet on the standing pose's feet: the bottom and middle of
  // idle frame 801 in rig units (the rig origin sits at the hips), so the
  // avatar stays put when it changes sheets.
  const stand = drawListBounds(drawListFor(prep, 801), prep.shapeOf) || [0, 0, 0, 0];
  const feetY = oy + Math.round(stand[3]);
  const midX = ox + Math.round((stand[0] + stand[2]) / 2);
  return { name, frames, cells: frames.length, fw, fh, ox, oy, cols, rows, feetY, midX };
}

/** Paint one sheet at `scale` into a new canvas. */
export function paintSheet(prep, layout, scale, canvas = document.createElement('canvas')) {
  canvas.width = layout.cols * layout.fw * scale;
  canvas.height = layout.rows * layout.fh * scale;
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  layout.frames.forEach((fn, k) => {
    const cx = (k % layout.cols) * layout.fw * scale;
    const cy = Math.floor(k / layout.cols) * layout.fh * scale;
    ctx.save();
    ctx.beginPath();
    ctx.rect(cx, cy, layout.fw * scale, layout.fh * scale);
    ctx.clip();
    paintItems(ctx, drawListFor(prep, fn), prep.sources, [scale, 0, 0, scale, cx + layout.ox * scale, cy + layout.oy * scale]);
    ctx.restore();
  });
  return canvas;
}

/** GLITCH_AVATAR-style sheet def for a layout (anchored on the standing feet). */
export function sheetDef(layout, file) {
  return { file, cells: layout.cells, fw: layout.fw, fh: layout.fh, cols: layout.cols, rows: layout.rows, feetY: layout.feetY, midX: layout.midX };
}

/**
 * Paint one frame into a canvas, fitted and standing on its bottom edge
 * (character builder preview). boundsFrame fits every frame to one pose so
 * an animation does not change scale.
 */
export function paintPreview(prep, canvas, swfFrame = 801, { pad = 6, flip = false, boundsFrame = null } = {}) {
  const items = drawListFor(prep, swfFrame);
  prep.previewBounds ||= new Map();
  const bf = boundsFrame ?? swfFrame;
  if (!prep.previewBounds.has(bf)) prep.previewBounds.set(bf, drawListBounds(bf === swfFrame ? items : drawListFor(prep, bf), prep.shapeOf));
  const b = prep.previewBounds.get(bf) || [-40, -120, 40, 0];
  const w = canvas.width;
  const h = canvas.height;
  const s = Math.min((w - 2 * pad) / (b[2] - b[0]), (h - 2 * pad) / (b[3] - b[1]));
  const ctx = canvas.getContext('2d');
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.clearRect(0, 0, w, h);
  const tx = w / 2 - ((b[0] + b[2]) / 2) * s * (flip ? -1 : 1);
  const ty = h - pad - b[3] * s;
  paintItems(ctx, items, prep.sources, [flip ? -s : s, 0, 0, s, tx, ty]);
  return canvas;
}

/**
 * Bake every sheet of a look. Yields between sheets so a runtime bake does
 * not stall the game; resolves { sheets: { name: { canvas, def } }, scale }.
 */
export async function bakeLook(prep, scale, { onSheet } = {}) {
  const sheets = {};
  for (const name of SHEET_ORDER) {
    const layout = sheetLayout(prep, name);
    const canvas = paintSheet(prep, layout, scale);
    sheets[name] = { canvas, def: sheetDef(layout, `${name}.png`) };
    onSheet?.(name, sheets[name]);
    await new Promise((r) => setTimeout(r, 0));
  }
  return { sheets, scale };
}
